/* Frontend-only campaign model. All prospects and performance data are fictional. */
(function(root){
const names=['Aarav Mehta','Ananya Rao','Kabir Sethi','Meera Iyer','Rohan Shah','Tara Kapoor','Dev Malhotra','Priya Nair','Arjun Bhat','Riya Sen','Neil Sinha','Isha Patel','Vikram Bose','Sana Ali','Aditya Jain','Naina Gupta','Rahul Menon','Maya Desai','Kunal Roy','Diya Verma','Ankit Shah','Leena Das','Siddharth Rao','Avni Joshi','Nikhil Kapoor','Zoya Khan','Varun Singh','Pooja Mehta','Sameer Rao','Aditi Bose'];
const companies=['Layerbase','Metricflow','Stacklane','Orbitdesk','Fableworks','Northbeam Labs','Loopcraft','Brightdesk','Relaypath','Cloudnest','Threadwise','Scalegrid','Draftline','Signalnest','Fieldkit','Launchwell','Bytehaven','Workloom','Daybreak','Cohortly','Teamforge','Pointwise','Nimblepath','Growframe','Crestline','Taskfield','Waymark','Zentro','Openfield','Flowlane'];
const signals=['Hiring','Funding','New leadership','Expansion'];
const facts=['is hiring three sales development representatives','announced a seed round to grow its commercial team','appointed a new head of growth','is expanding into a second market'];
const account=()=>({company:'Northstar',website:'northstar.example',offering:'We help B2B SaaS teams build a repeatable outbound process, from finding the right prospects to personalized outreach.',icp:'Founders and heads of growth at B2B SaaS companies with 10–200 employees in India.',proof:'Hands-on setup, a clear qualification process, and tailored messaging.',tone:'Conversational',sender:'Maya',email:'maya@northstar.example',signature:'Maya\nNorthstar',exclusions:'Existing customers, competitors, agencies, and active opportunities'});
function campaign(ctx,prompt=''){return {id:'c'+Date.now(),name:prompt?'SaaS growth · signal-led outreach':'Untitled campaign',prompt,audience:prompt||ctx.icp,offer:ctx.offering,contextOrigin:prompt?'Assistant brief + company context':'Company context',source:'research',sourceRef:'',signals:['Hiring','Funding'],freshness:30,min:25,max:30,target:28,quality:80,exclusions:ctx.exclusions,status:'draft',step:0,leads:[],selected:[],drafts:{},tone:ctx.tone,length:'Balanced',angle:'Signal-led',cta:'Start a conversation',followup:false,delay:3,days:['Mon','Tue','Wed','Thu','Fri'],time:'09:00',timezone:'Asia/Kolkata',approval:'daily',events:[],batch:1,history:false,created:Date.now()}}
function discover(c,shortfall=false){const limit=shortfall?20:30;return names.slice(0,limit).map((name,i)=>{const sig=c.signals[i%c.signals.length]||'Hiring';const si=signals.indexOf(sig);const quality=i<26?96-i%14:i<28?73:58;return {id:c.id+'b'+c.batch+'l'+i,name,company:companies[i],role:i%3?'Head of Growth':'Founder & CEO',email:i===27?'':name.split(' ')[0].toLowerCase()+'@'+companies[i].toLowerCase().replace(/ /g,'')+'.example',score:quality,status:i>=28?'excluded':quality<c.quality||i===27?'review':'qualified',signal:sig,fact:companies[i]+' '+facts[Math.max(0,si)]+'.',reason:i>=28?'Outside the target company-size range':i===27?'Email address missing; identity requires review':quality<c.quality?'Insufficient evidence for the qualification threshold':'Role, company profile, and recent signal match the campaign brief.',source:c.source==='salesnav'?'Sales Navigator sample + email enrichment sample':'Company website · sample research',emailStatus:i===27?'Missing':'Sample verified',initials:name.split(' ').map(x=>x[0]).join(''),date:'2 days ago'}})}
function eligible(c){return c.leads.filter(l=>l.status==='qualified'&&l.email&&l.score>=c.quality)}
function selected(c){return eligible(c).filter(l=>c.selected.includes(l.id))}
function variants(c){return c.followup?['intro','followup']:['intro']}
function key(l,v){return l.id+':'+v}
function draft(c,l,v,ctx){const k=key(l,v);if(!c.drafts[k]){let greeting=c.tone==='Professional'?'Hello':'Hi';let body=v==='followup'?`${greeting} ${l.name.split(' ')[0]},\n\nFollowing up on my earlier note. ${c.offer}\n\nWould this be relevant for your team at ${l.company}? Happy to leave it here if the timing isn’t right.\n\n${ctx.signature}`:`${greeting} ${l.name.split(' ')[0]},\n\n${c.angle==='Signal-led'?`I noticed ${l.fact.charAt(0).toLowerCase()+l.fact.slice(1)}`:`Your work at ${l.company} caught my attention.`}\n\n${c.offer}\n\n${c.cta==='Book a meeting'?'Would you be open to a 15-minute conversation next week?':c.cta==='Ask permission'?'Would it be useful if I sent a short overview?':'Is this something your team is thinking about?'}\n\n${ctx.signature}`;if(c.length==='Concise')body=`${greeting} ${l.name.split(' ')[0]},\n\n${c.offer}\n\nWorth a quick conversation for ${l.company}?\n\n${ctx.signature}`;c.drafts[k]={subject:v==='followup'?`Re: A thought for ${l.company}`:`A thought for ${l.company}`,body,approved:false}}return c.drafts[k]}
function draftList(c,ctx){return selected(c).flatMap(l=>variants(c).map(v=>({l,v,key:key(l,v),draft:draft(c,l,v,ctx)})))}
function approved(c,ctx){return draftList(c,ctx).filter(x=>x.draft.approved).length}
function invalidate(c){c.drafts={}}
function blockers(c,ctx){const errors=[];if(!c.name.trim()||!c.audience.trim()||!c.offer.trim())errors.push('Complete your campaign brief.');if(!c.signals.length)errors.push('Choose at least one discovery signal.');if(!selected(c).length)errors.push('Select at least one qualified prospect.');if(draftList(c,ctx).some(x=>!x.draft.approved||!x.draft.body.trim()||!x.draft.subject.trim()))errors.push('Approve every initial and follow-up email.');if(!c.days.length||!/^([01]\d|2[0-3]):[0-5]\d$/.test(c.time))errors.push('Choose a valid schedule.');return errors}
root.OutboundModel={account,campaign,discover,eligible,selected,variants,key,draft,draftList,approved,invalidate,blockers};
})(typeof module==='object'?module.exports:window);
